// layouts/default/DefaultLayout.js
import { Component } from '@odoo/owl'

export default class DefaultLayout extends Component {
  static template = 'DefaultLayout'
}

import { Component } from '@odoo/owl'

export default class DashboardPage extends Component {
  static template = 'DashboardPage'
  static layout = 'admin'   // uses AdminLayout
}

import { Component } from '@odoo/owl'

export default class IndexPage extends Component {
  static template = 'IndexPage'
  // No layout set → 'default' layout is used automatically
}

import { registerLayout, setDefaultLayout, getLayout } from 'metaowl'

// Register a layout manually
registerLayout('admin', AdminLayout)

// Change the default layout
setDefaultLayout('admin')

// Get a layout component by name
const Layout = getLayout('admin')

export default class LoginPage extends Component {
  static template = 'LoginPage'
  static layout = false   // full-screen, no layout
}

import { setParentLayout, getParentLayout, registerLayout } from 'metaowl'
registerLayout('blog', BlogLayout) registerLayout('post', PostLayout)
// Set blog as parent of post setParentLayout('post', 'blog')
// Returns 'blog' getParentLayout('post')

import { getLayoutChain, setParentLayout } from 'metaowl'
setParentLayout('post', 'blog') setParentLayout('blog', 'default')
// Returns ['post', 'blog', 'default'] getLayoutChain('post')

import { createNestedLayoutWrapper, getLayout } from 'metaowl'
const layouts = [getLayout('default'), getLayout('blog'), getLayout('post')] const page = MyPageComponent
const Wrapper = createNestedLayoutWrapper(layouts, page, { customProp: 'value' })

import { defineNestedLayout } from 'metaowl'

@defineNestedLayout('post', 'blog', { theme: 'light' })
export default class PostLayout extends Component {
  static template = 'PostLayout'
}
